-- Check if table exists first
SELECT COUNT(*) FROM events WHERE event_type = 'payment_clearing';
-- If table doesn't exist, use correct table name
SELECT COUNT(*) FROM your_actual_table_name WHERE event_type = 'payment_clearing';

SELECT COUNT(*) FROM events 
WHERE event_type = 'goods_issue' 
AND EXTRACT(YEAR FROM timestamp) = 2005;

SELECT COUNT(DISTINCT relations.from_object_id) 
FROM relations 
WHERE relation_type = 'order_to_delivery';

-- Option 1: Add table schema prefix if needed
SELECT COUNT(*) FROM schema_name.relations WHERE relation_type = 'order_to_customer';

-- Option 2: Use COUNT(1) which is slightly more efficient in some databases
SELECT COUNT(1) FROM relations WHERE relation_type = 'order_to_customer';

-- Option 3: Add alias for clarity
SELECT COUNT(*) AS order_customer_count 
FROM relations 
WHERE relation_type = 'order_to_customer';
